<?php

class CF1342E {
    const MD = 998244353;

    private $ff;
    private $gg;
    private $tokens;
    private $pos = 0;

    public function __construct() {
        $data = stream_get_contents(STDIN);
        $this->tokens = preg_split('/\s+/', trim($data), -1, PREG_SPLIT_NO_EMPTY);
        $this->pos = 0;
    }

    private function next() {
        return $this->tokens[$this->pos++];
    }

    private function nextInt() {
        return (int) $this->next();
    }

    private function nextLong() {
        return (int) $this->next();
    }

    private function println($s) {
        echo $s, "\n";
    }

    public function power($a, $k) {
        if ($k == 0)
            return 1;
        $p = $this->power($a, $k >> 1);
        $p = $p * $p % self::MD;
        if (($k & 1) == 1)
            $p = $p * $a % self::MD;
        return $p;
    }

    public function ch($n, $k) {
        return $this->ff[$n] * $this->gg[$k] % self::MD * $this->gg[$n - $k] % self::MD;
    }

    public function main() {
        $n = $this->nextInt();
        $k_ = $this->nextLong();
        if ($k_ >= $n) {
            $this->println(0);
            return;
        }
        $c = $n - (int) $k_;
        $this->ff = array_fill(0, $n + $n, 0);
        $this->gg = array_fill(0, $n + $n, 0);
        $f = 1;
        for ($i = 0; $i < $n + $n; $i++) {
            $this->ff[$i] = $f;
            $this->gg[$i] = (int) $this->power($f, self::MD - 2);
            $f = (int) ($f * ($i + 1) % self::MD);
        }
        $ans = 0;
        for ($a = 1; $a <= $c; $a++) {
            $x = $this->power($a, $n) * $this->ch($c, $a) % self::MD;
            $ans += ($c - $a) % 2 == 0 ? $x : -$x;
        }
        $ans %= self::MD;
        if ($ans < 0)
            $ans += self::MD;
        $ans = $ans * $this->ch($n, $c) % self::MD;
        if ($k_ > 0)
            $ans = $ans * 2 % self::MD;
        $this->println($ans);
    }
}

$o = new CF1342E();
$o->main();
